def read_text(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []
    for rel in FILES:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return manifest


def restore(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def patch_main(text_value: str) -> str:
    if MARK_MAIN in text_value:
        return text_value

    import_line = (
        "from app.routers.mn_official_reports import (\n"
        "    router as mn_official_reports_router,\n"
        "    install_mn_official_report_redirects,\n"
        ")\n"
    )
    if "mn_official_reports_router" not in text_value:
        anchor = re.search(r"(?m)^BASE_DIR\s*=", text_value)
        if anchor:
            text_value = text_value[:anchor.start()] + import_line + "\n" + text_value[anchor.start():]
        else:
            imports = list(re.finditer(r"(?m)^from app\.routers\..*$", text_value))
            if not imports:
                raise RuntimeError("Không tìm thấy vị trí import router trong app/main.py")
            pos = imports[-1].end()
            text_value = text_value[:pos] + "\n" + import_line.rstrip() + text_value[pos:]

    if "app.include_router(mn_official_reports_router)" not in text_value:
        includes = list(re.finditer(r"(?m)^app\.include_router\([^\n]+\)\s*$", text_value))
        if not includes:
            raise RuntimeError("Không tìm thấy app.include_router trong app/main.py")
        pos = includes[-1].end()
        block = (
            "\n# === " + MARK_MAIN + " ===\n"
            "app.include_router(mn_official_reports_router)\n"
            "install_mn_official_report_redirects(app)\n"
        )
        text_value = text_value[:pos] + block + text_value[pos:]
    elif MARK_MAIN not in text_value:
        text_value += "\n# === " + MARK_MAIN + " ===\n"
    return text_value


def _replace_report_link(text_value: str, old_code: str, new_path: str, new_label: str) -> str:
    # Menu hiện tại dùng href dạng /bao-cao?report_type=<mã>.
    # Thay trực tiếp href, đồng thời thay đúng nhãn hiển thị bằng các biến thể đã biết.
    text_value = text_value.replace(
        f'href="/bao-cao?report_type={old_code}"',
        f'href="{new_path}"',
    )
    text_value = text_value.replace(
        f"href='/bao-cao?report_type={old_code}'",
        f"href='{new_path}'",
    )
    if old_code == "PCGD_MN_M1_2025":
        for old_label in (
            "MN-M1 – Phổ cập giáo dục Mầm non",
            "MN-M1 - Phổ cập giáo dục Mầm non",
            "Báo cáo MN-M1",
            "MN-M1",
        ):
            text_value = text_value.replace(old_label, new_label)
    elif old_code == "PCGD_MN_01_GV_2025":
        for old_label in (
            "MN-01-GV – Đội ngũ giáo viên",
            "MN-01-GV - Đội ngũ giáo viên",
            "Báo cáo MN-01-GV",
        ):
            text_value = text_value.replace(old_label, new_label)
    return text_value


def patch_menu(text_value: str) -> str:
    if MARK_MENU in text_value:
        return text_value
    text_value = _replace_report_link(
        text_value,
        "PCGD_MN_M1_2025",
        "/bao-cao/mn-01-te",
        "MN-01-TE – Thống kê trẻ em Mầm non theo độ tuổi",
    )
    text_value = _replace_report_link(
        text_value,
        "PCGD_MN_01_GV_2025",
        "/bao-cao/mn-01-gv-bgd",
        "MN-01-GV – Thống kê đội ngũ CBQL, giáo viên, nhân viên",
    )
    # Fallback đổi tên hiển thị nếu cấu trúc anchor của menu khác dự kiến.
    text_value = text_value.replace("MN-M1", "MN-01-TE")
    text_value = text_value.replace(
        "MN-01-GV – Đội ngũ giáo viên",
        "MN-01-GV – Thống kê đội ngũ CBQL, giáo viên, nhân viên",
    )
    text_value = text_value.rstrip() + f"\n{{# === {MARK_MENU} === #}}\n"
    return text_value


