def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def verify_xlsx(path: Path, expected_sha: str, sheet_marker: str, text_marker: str) -> None:
    if sha256(path) != expected_sha:
        raise RuntimeError(f"Mẫu Excel bị thay đổi byte: {path.name}")
    with zipfile.ZipFile(path, "r") as zf:
        if zf.testzip() is not None:
            raise RuntimeError(f"Mẫu Excel lỗi ZIP/CRC: {path.name}")
        combined = b"\n".join(
            zf.read(name)
            for name in zf.namelist()
            if name.endswith(".xml") and ("workbook" in name or "sharedStrings" in name or "worksheets" in name)
        ).decode("utf-8", errors="ignore")
        if sheet_marker not in combined or text_marker not in combined:
            raise RuntimeError(f"Mẫu Excel không đúng cấu trúc dự kiến: {path.name}")


def verify() -> None:
    subprocess.run([sys.executable, "-m", "py_compile", str(MAIN)], cwd=PROJECT, check=True)
    subprocess.run([sys.executable, "-m", "py_compile", str(REPORT_CENTER)], cwd=PROJECT, check=True)
    subprocess.run([sys.executable, "-m", "py_compile", str(ROUTER)], cwd=PROJECT, check=True)

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    env.get_template("reports/mn_official_report.html")
    env.get_template("partials/dropdown_menu_v1.html")

    verify_xlsx(TE_TEMPLATE, TE_SHA256, "Thống kê trẻ em từ 0 đến 5 tuổi", "MN-01-TE")
    verify_xlsx(GV_TEMPLATE, GV_SHA256, "MG", "MN-01-GV")

    main_text = read_text(MAIN)
    menu_text = read_text(MENU)
    router_text = read_text(ROUTER)
    for marker in (
        MARK_MAIN,
        "app.include_router(mn_official_reports_router)",
        "install_mn_official_report_redirects(app)",
    ):
        if marker not in main_text:
            raise RuntimeError(f"app/main.py thiếu: {marker}")
    if "MN-M1" in menu_text:
        raise RuntimeError("Menu vẫn còn tên MN-M1 sau khi thay mẫu.")
    for marker in (
        "/bao-cao/mn-01-te",
        "/bao-cao/mn-01-gv-bgd",
        "PCGD_MN_M1_2025",
        "PCGD_MN_01_GV_2025",
        "Các ô này được giữ trống, không tự suy đoán thành 0",
    ):
        if marker not in router_text:
            raise RuntimeError(f"Router báo cáo mẫu mới thiếu: {marker}")


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


